import{_ as e,c as r,o as i,af as t}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"5、【需】 乾下坎上","description":"橫渠易說 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"橫渠易說 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"classics/hengqu/007.md","filePath":"classics/hengqu/007.md"}'),h={name:"classics/hengqu/007.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>剛健而不陷而能俟時，故有孚於光亨也。訟、需、坎皆言“有學”，必然之理也。又如未濟“飲酒濡首”亦言“有孚”，襲同此。</p><p>彖曰：需，須也，險在前也，剛健而不陷，其義不困窮矣。“需有孚光亨貞吉”，位乎天位，以正中也。</p><p>“利涉大川”，往有功也。</p><h3 id="象曰-雲上放天-需-君子以飲食宴樂。" tabindex="-1">象曰：雲上放天，需，君子以飲食宴樂。 <a class="header-anchor" href="#象曰-雲上放天-需-君子以飲食宴樂。" aria-label="Permalink to “象曰：雲上放天，需，君子以飲食宴樂。”">​</a></h3><p>“雲上於天，需，君子以飲食宴樂”，九五，需於酒食貞吉”，未濟亦“有孚於飲酒”，以陰在前，無所施為，惟於飲食而已。</p><h3 id="初九-需於郊-利用恆-無咎。-象曰-需於郊-不犯難行也。-利用恆無咎-未失常也。" tabindex="-1">初九，需於郊，利用恆，無咎。 象曰：“需於郊”，不犯難行也。“利用恆無咎”，未失常也。 <a class="header-anchor" href="#初九-需於郊-利用恆-無咎。-象曰-需於郊-不犯難行也。-利用恆無咎-未失常也。" aria-label="Permalink to “初九，需於郊，利用恆，無咎。 象曰：“需於郊”，不犯難行也。“利用恆無咎”，未失常也。”">​</a></h3><h3 id="九二-需於沙-小有言-終吉。-象曰-需於沙-衍在中也。雖小有言-以吉終也。" tabindex="-1">九二，需於沙，小有言，終吉。 象曰：“需於沙”，衍在中也。雖小有言，以吉終也。 <a class="header-anchor" href="#九二-需於沙-小有言-終吉。-象曰-需於沙-衍在中也。雖小有言-以吉終也。" aria-label="Permalink to “九二，需於沙，小有言，終吉。 象曰：“需於沙”，衍在中也。雖小有言，以吉終也。”">​</a></h3><h3 id="九三-需於泥-致寇至。-象曰-需於泥-災在外也。自我致寇-敬慎不敗也。" tabindex="-1">九三，需於泥，致寇至。 象曰：“需於泥”，災在外也。自我致寇，敬慎不敗也。 <a class="header-anchor" href="#九三-需於泥-致寇至。-象曰-需於泥-災在外也。自我致寇-敬慎不敗也。" aria-label="Permalink to “九三，需於泥，致寇至。 象曰：“需於泥”，災在外也。自我致寇，敬慎不敗也。”">​</a></h3><h3 id="六四-需於血-出自穴。-象曰-需於血-順以聽也。" tabindex="-1">六四，需於血，出自穴。 象曰：“需於血”，順以聽也。 <a class="header-anchor" href="#六四-需於血-出自穴。-象曰-需於血-順以聽也。" aria-label="Permalink to “六四，需於血，出自穴。 象曰：“需於血”，順以聽也。”">​</a></h3><p>以柔居陰，不能御弦，來則聽順而闢其路。</p><h3 id="九五-需於酒食-貞吉。-象曰-酒食貞吉-以中正也。" tabindex="-1">九五，需於酒食，貞吉。 象曰：酒食貞吉，以中正也。 <a class="header-anchor" href="#九五-需於酒食-貞吉。-象曰-酒食貞吉-以中正也。" aria-label="Permalink to “九五，需於酒食，貞吉。 象曰：酒食貞吉，以中正也。”">​</a></h3><h3 id="上六-入於穴-有不速之客三人來-敬之終吉。-象曰-不速之客來-敬之終吉。-雖不當位-未大失也。" tabindex="-1">上六，入於穴，有不速之客三人來，敬之終吉。 象曰：“不速之客來，敬之終吉。”雖不當位，未大失也。 <a class="header-anchor" href="#上六-入於穴-有不速之客三人來-敬之終吉。-象曰-不速之客來-敬之終吉。-雖不當位-未大失也。" aria-label="Permalink to “上六，入於穴，有不速之客三人來，敬之終吉。 象曰：“不速之客來，敬之終吉。”雖不當位，未大失也。”">​</a></h3><p>上無所出，故降人自穴，恭以納之，雖處極上，不至於失。</p>',14)])])}const f=e(h,[["render",l]]);export{_ as __pageData,f as default};
